import{_ as t,a0 as l,w as e,s as r,I as u,x as i,a1 as x,A as L,ao as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const A=JSON.parse('{"title":"Linux的未來：進化無處不在 | LCTT x X-CMD","titleTemplate":false,"description":"Linux的未來：進化無處不在 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux的未來：進化無處不在 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux的未來：進化無處不在 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/The future of Linux--Evolving everywhere","title":"Linux的未來：進化無處不在","tag":"201311","desc":""},"relativePath":"201311/The future of Linux--Evolving everywhere.md","filePath":"[post].md"}'),d={name:"201311/The future of Linux--Evolving everywhere.md"};function s(f,n,m,a,T,g){const p=l("Link");return e(),r("div",null,[n[21]||(n[21]=u("h1",{id:"linux的未來-進化無處不在",tabindex:"-1"},[i("Linux的未來：進化無處不在 "),u("a",{class:"header-anchor",href:"#linux的未來-進化無處不在","aria-label":"Permalink to “Linux的未來：進化無處不在”"},"​")],-1)),u("p",null,[n[1]||(n[1]=u("em",null,"InfoWorld",-1)),n[2]||(n[2]=i(" —— Mark Shuttleworth之前關閉了",-1)),x(p,{href:"https://bugs.launchpad.net/ubuntu/+bug/1"},{default:L(()=>[...n[0]||(n[0]=[i("Ubuntu Linux的第一號bug",-1)])]),_:1}),n[3]||(n[3]=i("（“微軟擁有最高的市場佔有率”），導致了一些爭議，也引出了一些意味深長的討論，討論自從1991年Linus Torvalds以個人玩物項目發明Linux以來，Linux所走過的路。",-1))]),n[22]||(n[22]=o("<p>微軟也許不會那麼快退出桌面系統的歷史舞台，但是隨着Linux逐漸成長成為IT行業的一塊重要基石，計算機的本質也已經完全改變。如今，從雲服務到手機操作系統，幾乎行業內的所有領域都受到了Linux的直接推動或間接影響。</p><p>###Linux體系：提交、審核、採納</p><p>伴隨着支持者的不斷增加，Linux的開發進程也在不斷加快。</p><p>但發展的方向又在何處？如果Linux的普及和開發程度正在接近頂峯，那接下來Linux將去往何方？因為Linux具有超高的定製性和超多的“分身”，也許沒有哪一個單獨的答案能夠回答這個問題。</p><p>或許，更重要的，是快速成長中的Linux如何應對挑戰，變得更加成熟穩定，成為在多個領域主導市場發展的領頭羊。接下來，讓我們分別從以下幾個方面嘗試預測一下Linux的未來：原材料、社區產品與企業貢獻、其特質所面對的各種挑戰、技術實力和成長方向。</p><p>###Linux作為原材料：彎曲、塑形，你想讓它是什麼樣都可以</p><p>如果用一個形容詞來總結Linux獨有的優點，那就是“可塑性(malleable)”。Linux是這樣一種原材料，可以裝訂切割，也可以為任意場合量身定做，小到嵌入式設備，大到大規模並行超級計算機。</p><p>但同時，這也是Linux的缺點之一。它千變萬化的特性使得它很少以“Linux”的本來面目出現 —— 相反，人們使用的是各種“基於Linux”的產品，例如Android、或家用路由器這樣的硬件設備。桌面Linux的多個發行版（之間往往不相容）也把最忠實的用户羣分割得七零八落。</p><p>Linux基金會執行董事Jim Zemlin承認，“Linux終端用户的體驗的的確確是支離破碎的，但這也是Linux的一個強大之處。”</p><p>“它就像一塊建築地基，使得Google能建立Android和Chromebooks，Amazon建立Kindle，Canonical建立Ubuntu，等等這樣的例子還有很多。所有這些產品對用户來説意味着不同的使用體驗，而選擇權完全在消費者自己手裏。”</p><p>Mark Baker，Canonical公司的Ubuntu服務器產品經理，目前負責領導Ubuntu項目。他的話更加具體準確地表明瞭這一觀點：“開源意味着選擇的自由。”開源自然會促進模組化，因此，無論你是一個技術宅男還是正在開發數據中心的系統架構師，“通過開源，你可以選擇最適合你的組件”。</p><p>但是IDC的操作環境分析師兼系統軟件項目副經理 Al Gillen 卻質疑這種完全放任自流的價值觀。“Linux是開源的，由此，任何人都可以修改代碼，把它變成別的什麼東西。但是，現代工業已經表明，沒有價值的產品會被淘汰，代碼的發展主線應當始終緊靠主流價值觀。”</p><p>Android用户對此有直接的深刻體會，諸多Android操作系統間存在着嚴重的碎片化問題。嚴格來説，儘管這並不都是Linux的責任，但是看看在Android之前就已經出現的無數五花八門的Linux桌面發行版吧，放任產品隨意修改，差異化實現又造成更大的影響 —— Android碎片化只是將這些問題生動放大了而已。</p><p>諷刺的是，即使“可塑性”真的是Linux的最大優勢，但過猶不及，Linux作為這樣的原材料將會付出成倍的代價。</p><p>Cloudera的工程部經理 Eric Sammer 並沒有孤立地看待這個問題，他認為Linux的用户羣“與Firefox或Apache等產品的用户羣並不一樣”，Linux“面向的並不是終端用户，而是操作系統類工程師”，因此它需要與“很多其他軟件一同建立一個完整的系統 —— 其中大部分軟件是捆綁發佈的，並對用户透明（例如boot loader）。”就如同Torvalds在Linux最初的內核發佈日誌中親自寫道，“只有內核，你什麼也幹不了。”</p><p>Android驗證了Gillen和Sammer以上兩人的觀點，作為Linux最受歡迎的“衍生品”，Android所有的附加值都來自於Google以及Google專門為其開發的App生態系統。因此説，Linux的可塑性只是它成為真正產品的第一步，正如下文中這些最成功的Linux擁護者 —— 企業，所熟悉的一樣。</p><p>###企業的貢獻：利還是弊？</p><p>Linux的另一個特點，它是一個合作產物，由眾多貢獻者共同努力締造而成。那麼，這些貢獻者從何而來？</p><p>答案：企業。企業是最主要的貢獻者，但是他們忠於利益，支持Linux只是為了自身的未來發展。除去Red Hat（不同於Canonical，RedHat是最為人所熟知的Linux解決方案供應商），排名前幾位的貢獻者主要包括Intel，IBM，德州儀器，甚至還有微軟。</p><p>Linux的所謂“靈活性”，即能夠運行在多個平台或設備上的能力，很大程度上來源於以上這些貢獻者，而他們的主要動力則來自於不斷萌發的自身需要：例如，微軟為Linux內核添加的代碼，大大改善了Linux在其產品Hyper-V下的運行狀況。</p><p>Sammer相信企業背景的發行版之所以能夠普及，是“因為Linux內核這樣的項目其複雜程度和准入門檻太高，一般水平的C程序員很難在有限的業餘時間內，僅憑個人能力，而不依靠企業的支持，跟上內核的更新進度、建立社區公信力，或者做出某些重大貢獻”。在他看來，企業恰恰有能力有資源支持這樣的努力，與之相比，高校和研究機構已被遠遠地拋在了後面。</p><p>但是企業發行版的普及就代表Linux已經陷入企業的控制了嗎？難道這就是Linux的未來？淪為資本的玩物？</p><p>其實最重要的不是看誰對Linux的貢獻最多，而是這種貢獻所代表的企業精神。不管是純粹為了圈錢，還是為了把掙來的錢都回饋於社區，無論這些企業最初的動機是什麼，作為Linux的貢獻者，它們始終對貢獻本身堅信不疑。</p><p>Mark Coggin，Linux紅帽企業版的市場高級總監，他堅信，“最佳的創新點是那些經過開源社區的無數參與者利用、改進後的方案。”</p><p>“我們所有的新點子都會先作為開源項目，尋求社區上游項目組的增益評估，然後才加入像紅帽企業版這樣的產品。我們希望那些為Linux內核及配套項目工作的每個人，也能擁有像我們一樣的眼光。”</p><p>還有一小部分觀點認為，企業發行版Linux其實是一種“被綁架的Linux”，正如Gillen所提倡的 —— 這是一種讓Linux“稍稍不那麼貼合主流用户羣需求”的方法。他確信，對Linux的商業化支持與商業優化“對Linux的開發模式大有裨益，而不是相反。”</p><p>###同樣的，對Zenmlin來説，Linux開發“並不是一個零和遊戲”</p><p>“如果移動領域的某位開發者改善了耗電量，另一位在數據中心工作的開發者會因此而受益，他可以使用前者的改進來確保自己的數據服務運行得更有效率，”Zemlin説道，“共享開發正是Linux如此強大的原因。”</p><p>同樣，企業開發也並非敵人，“人們為Linux的開發工作付費從來都不是壞事；這些錢款可以讓Linux的改善與創新變得更加迅捷快速。”</p><p>真正的問題是，Baker補充道，“一些超大型網絡公司對Linux作出改進並上線應用，但是卻為了保持自己的優勢，而把這些改進捂在自家門裏。”</p><p>GPL協議第三版 —— 從Linux發佈協議的一個早期版本改進而來 —— 當初修改該協議的部分原因就是為了應對上述行為。儘管如此，協議只能防止獲取他人代碼後作為Web服務重新開發。除此以外，並沒有什麼固有的方法（或法律手段）能夠禁止公司或個人在代碼開發完成後封閉獨佔這些改進後的代碼，也許，這就是Linux對全世界自由開放所不可避免的一部分社會成本吧。</p><p>###Linux面臨的最大威脅</p><p>感謝開源機制，Linux始終能夠作為一個開源項目，企業才無法像以前那麼獨斷專行。那除了企業，現在什麼才是Linux所面臨的最大威脅呢？</p><p>沒人會真的認為Linux會被版權欺詐或訴訟所威脅，更不會因此從OS版圖上消失。類似的最大一起訴訟案，SCO Group公司控告IBM案，被廣泛解釋為間接對Linux的攻擊，也最終以悲慘的失敗而告終（譯者注，該案件間接導致了SCO Group的破產）。</p><p>Coggin也傾向於該觀點：“依靠巨大的開發者網絡和全球範圍內的推廣傳播，Linux取得了巨大成功，這意味着它具有很強的韌性。儘管專利威脅一直都在增加，正如許多科技公司最近所做的那樣，但是看起來專利訴訟並不會對Linux產生任何實質性的威脅。”</p><p>除此以外，其他類似開源產品的競爭，甚至更加自由化的協議（例如各式各樣的BSD們），目前為止，都沒有真正達到能夠危及淘汰Linux的程度。</p><p>Sammer用一個單詞總結出了，在合法範圍內，Linux面臨的最大威脅：自滿！ —— 自滿地認為已經成為所有領域的市場領導者。</p><p>他説，“如果你正在競爭第一名的位置，你常常願意更開放地做出改變，無論是過程上的、心態上的，還是有關發展路線的，甚至維持現狀本身。想想Firefox被Chrome以如此快的速度搶走了如此多的份額，再想想當年的商業化Unix們被Linux搶佔江山，這樣的例子還有很多很多。”</p>",38)),u("p",null,[n[5]||(n[5]=i("大致根據同樣的思路，Zemlin看到了這樣一種威脅，面對日益增長的需求，Linux的天才開發者們才氣有餘，但經驗不足，因此這才有了",-1)),x(p,{href:"http://training.linuxfoundation.org/"},{default:L(()=>[...n[4]||(n[4]=[i("Linux培訓",-1)])]),_:1}),n[6]||(n[6]=i("項目。",-1))]),n[23]||(n[23]=o("<p>Gillen發現的威脅來自於社區的變化，“隨着時間推移，Linux的主流用户羣 —— 社區，正在從企業的客户（服務的消費者）轉變為服務的提供者。”</p><p>這樣一種變化可能會導致Linux用户被迫作為Linux服務提供者的同時，卻完全無法將自己的智慧和創新回饋社區。這種變化也許會持續十幾年甚至更長，但它“對整個Linux世界都具有深遠的消極影響，包括各個Linux商業發行商在內。”</p><p>Linux所要面對的另外一個潛在威脅是公司兼併 —— 這並不會威脅到Linux本身，但它可能會間接導致各種各樣的可能性。Baker擔心移動設備的快速增長，除了受Linux自身的發展影響外，更多的會受到來自企業施加的影響。</p><p>他説，“這就是為什麼我們需要諸如Ubuntu和Firefox這樣的第二選擇，目的就是為那些上網時不願受Apple和Google擺佈的人們提供真正的替代品。”</p><p>説到Google，Google是Android的發展道路上最堅定的捍衞者。圍繞Android作為Linux發展而來這一話題，有許多反對意見的爭論，這樣的爭論對於Google的世界觀來説，就像與它的首頁相比較一樣，稍顯多餘，同時它們也不符合Linux（自由開放）的精神。</p><p>簡而言之，目前Linux面臨的最大威脅來自於它自身 —— 無意中，衡量Linux產品的第一標準已經變成了如何讓它看起來更吸引人。一直以來，Linux所固有的靈活性和可塑性幫助它戰勝自滿和企業兼併，克服重重困難，但如今還能否一如既往，情況並不明朗。</p><p>###路在何方？</p><p>毫無疑問，無論從哪個層面來看，Linux現在都正處在關鍵的岔路口，它將去往何方，又將付出怎樣的代價，都值得探討。</p><p>Linux最明顯的未來之路，首先，它不僅僅是一塊基石，或者説不僅僅是一種建立基礎設施的途徑；其次，它應當減少過多的產品形式；最後，真正的革新，不僅僅是拓展Linux本身，還要拓展其作為發現問題解決問題的創新辦法。目前還很少有人如此對待Linux，要想真正做到這一點，除了呼籲更多的人改變對Linux的看法，還必須打破技術壁壘，將眼光放得更長遠。</p><p>對此，Coggin説道：“Linux正在逐漸成為一個更加成套或靈活的操作系統，進而超越其作為一個基礎設施平台的作用。我們看到，開發者和架構師們正在使用Linux建立新一代解決方案，創造出新一代的企業架構。”這些工作中的大部分已經開始付諸實施，他説道，包括“雲計算、大數據、移動領域以及社交網絡等多個方面”。</p><p>Gillen也同意上述觀點，Linux“即將成為公共雲基礎設施中非常關鍵的一個部分，由此，Linux確保了它在現代工業中能夠長期發揮作用。”</p>",11)),u("p",null,[n[8]||(n[8]=i("Baker説道，“Linux已經在運行着雲業務，這是毫無疑問的，它需要鞏固自己作為基礎設施平台的位置 —— 這意味着它需要時刻保持最新的技術領先優勢，例如ARM服務芯片、超大規模集成電路、網絡設計，以及所有的軟件設計數據中心。”上述這些工作應當可以作為開源系統硬件設計（例如",-1)),x(p,{href:"http://www.opencompute.org/2013/05/08/up-next-for-the-open-compute-project-the-network/"},{default:L(()=>[...n[7]||(n[7]=[i("開源計算機項目",-1)])]),_:1}),n[9]||(n[9]=i("）的有效補充。",-1))]),n[24]||(n[24]=u("p",null,"###Linux體系：提交、審核、採納",-1)),n[25]||(n[25]=u("p",null,"伴隨着正面需求不斷增長，Linux的開發進程也在不斷加快。",-1)),n[26]||(n[26]=u("p",null,"Linux作為普遍存在的基礎設施元素，其中一個潛在的缺點就是它有可能成為商業化的制度產物，正如曾經它所取代的閉源Unix們。但是Zemlin認為，Linux極大的靈活性在這方面發揮了作用：“十幾年前，如果你問到Linus Torvalds或其他社區成員，Linux是否會比其他任何平台都要更多的裝到移動電話裏，他們當然會説‘不會’。所以，我們要做的只是注視Linux的發展，不要嘗試去預測它，因為所有的預測幾乎都會是錯誤的。”",-1)),n[27]||(n[27]=u("p",null,"另一個重要的未來發展方向，就像上面提到的，“獨立於Google之外，在移動領域有更大的發展，”Baker如此預測道。像Mozilla專門針對移動電話的Firefox操作系統項目，就是這樣一種典型的嘗試，儘管在Google的存在下，以及Android如此巨大的市場份額面前，其成功的幾率並不明朗。",-1)),n[28]||(n[28]=u("p",null,"最後，最關鍵的問題，誰將擔負起指引Linux未來之路的責任。因為Linux可以由其他人任意複製(fork)並開發，歷史證明，擁有單一核心開發團隊對於Linux來説是最好的，同時要求基於該團隊的所有項目，其核心都能貫穿始終。",-1)),n[29]||(n[29]=u("p",null,"這樣核心團隊能夠承擔更多的責任，以推動Linux彌補現有或將來可能出現的不足，避免閉門造車式的技術封鎖，最終使Linux成為它最應該成為的樣子。",-1)),n[30]||(n[30]=u("p",null,"如果Linux的未來真的無處不在，現在沒有人能夠想像得到它會是什麼樣子 —— 這是一件好事，難道不是嗎？",-1)),n[31]||(n[31]=u("hr",null,null,-1)),u("p",null,[n[11]||(n[11]=i("via: ",-1)),x(p,{href:"http://www.networkworld.com/news/2013/101513-the-future-of-linux-evolving-274829.html"},{default:L(()=>[...n[10]||(n[10]=[i("http://www.networkworld.com/news/2013/101513-the-future-of-linux-evolving-274829.html",-1)])]),_:1})]),u("p",null,[n[14]||(n[14]=i("譯者：",-1)),x(p,{href:"http://blog.csdn.net/tinyeyeser"},{default:L(()=>[...n[12]||(n[12]=[i("Mr小眼兒",-1)])]),_:1}),n[15]||(n[15]=i(" 校對：",-1)),x(p,{href:"https://github.com/wxy"},{default:L(()=>[...n[13]||(n[13]=[i("wxy",-1)])]),_:1})]),u("p",null,[n[18]||(n[18]=i("本文由 ",-1)),x(p,{href:"https://github.com/LCTT/TranslateProject"},{default:L(()=>[...n[16]||(n[16]=[i("LCTT",-1)])]),_:1}),n[19]||(n[19]=i(" 原創翻譯，",-1)),x(p,{href:"http://linux.cn/"},{default:L(()=>[...n[17]||(n[17]=[i("Linux中國",-1)])]),_:1}),n[20]||(n[20]=i(" 榮譽推出",-1))])])}const v=t(d,[["render",s]]);export{A as __pageData,v as default};
